-- Saudi Arabia deep-dive content translations (ES/DE/FR)

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (Fatoora)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a partir de julio de 2026 y se proporciona con fines informativos generales, no como asesoramiento legal o fiscal. Los calendarios de olas de ZATCA, las especificaciones técnicas y la aplicación de sanciones siguen evolucionando — confirme los requisitos actuales directamente en el portal Fatoora de ZATCA antes de construir una integración.', 'El despliegue de ZATCA es un verdadero modelo de dos fases: primero todos tuvieron que generar facturas electrónicas, luego — de forma mucho más exigente — integrarse directamente con el gobierno en olas según la facturación.', 'El listón técnico de la Fase 2 es realmente alto: sellado criptográfico, contenido obligatorio en árabe y un código QR que incluye nueve etiquetas de datos distintas.', 'Arabia Saudí aplica uno de los modelos de compensación más estrictos de este tracker: una factura B2B sin la respuesta de compensación de ZATCA simplemente no tiene efecto fiscal.', 'La integración es un proceso técnico genuinamente multietapa — reserve tiempo real para la generación de certificados y las pruebas en el entorno de pruebas, no solo para el mapeo de formato.', 'La multa en sí es solo una parte de la exposición — los comportamientos de software prohibidos conllevan su propio escrutinio independiente.' FROM countries WHERE name_en = 'Saudi Arabia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentralisiertes Clearing (Fatoora)', 'Diese Detailseite spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient allgemeinen Informationszwecken, nicht der Rechts- oder Steuerberatung. ZATCA-Wellenpläne, technische Spezifikationen und die Durchsetzung von Bußgeldern entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt im Fatoora-Portal von ZATCA, bevor Sie eine Integration aufbauen.', 'ZATCAs Einführung ist ein echtes Zweiphasenmodell: Zunächst mussten alle E-Rechnungen erstellen, dann — deutlich anspruchsvoller — sich in Wellen nach Umsatz direkt in die Regierung integrieren.', 'Die technische Messlatte von Phase 2 liegt wirklich hoch: kryptografische Stempelung, verpflichtender arabischer Inhalt und ein QR-Code, der neun einzelne Datenmarkierungen enthält.', 'Saudi-Arabien betreibt eines der strengsten Clearing-Modelle in diesem Tracker: Eine B2B-Rechnung ohne die Freigabeantwort von ZATCA hat schlicht keine steuerliche Wirkung.', 'Die Integration ist ein wirklich mehrstufiger technischer Prozess — planen Sie echte Zeit für die Zertifikatserstellung und Sandbox-Tests ein, nicht nur für das Format-Mapping.', 'Das Bußgeld selbst ist nur ein Teil des Risikos — verbotene Softwarefunktionen unterliegen einer eigenen, separaten Prüfung.' FROM countries WHERE name_en = 'Saudi Arabia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (Fatoora)', 'Cette page d''analyse reflète les orientations techniques publiquement disponibles en date de juillet 2026 et est fournie à titre informatif général, non comme un avis juridique ou fiscal. Les calendriers de vagues de ZATCA, les spécifications techniques et l''application des sanctions continuent d''évoluer — confirmez les exigences actuelles directement sur le portail Fatoora de ZATCA avant de construire une intégration.', 'Le déploiement de ZATCA est un véritable modèle en deux phases : d''abord tout le monde a dû générer des factures électroniques, puis — de façon bien plus exigeante — s''intégrer directement au gouvernement par vagues selon le chiffre d''affaires.', 'La barre technique de la phase 2 est réellement élevée : cachet cryptographique, contenu obligatoire en arabe, et un code QR intégrant neuf balises de données distinctes.', 'L''Arabie saoudite applique l''un des modèles de contrôle les plus stricts de ce tracker : une facture B2B sans la réponse de contrôle de ZATCA n''a tout simplement aucun effet fiscal.', 'L''intégration est un processus technique véritablement multi-étapes — prévoyez du temps réel pour la génération de certificats et les tests en bac à sable, pas seulement pour la correspondance de format.', 'L''amende elle-même n''est qu''une partie de l''exposition — les comportements logiciels interdits font l''objet d''un contrôle distinct.' FROM countries WHERE name_en = 'Saudi Arabia';

