INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formato', '[["Sintaxis", "XML UBL 2.1, con extensiones específicas de ZATCA"], ["Empaquetado de factura estándar", "PDF/A-3 con XML incrustado"], ["Idioma", "Árabe, legible por máquina (bilingüe habitual en la práctica)"]]', 'El empaquetado PDF/A-3 con XML incrustado refleja el enfoque Factur-X de Francia — una representación legible por humanos junto con los datos legibles por máquina en un único archivo.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Controles criptográficos', '[["Algoritmo de firma", "ECDSA (Elliptic Curve Digital Signature Algorithm)"], ["Credencial", "Identificador de Sello Criptográfico (CSID)"], ["Capa gubernamental", "ZATCA aplica su propio sello con su clave privada tras la compensación"]]', 'La cadena de confianza va de proveedor → ZATCA → receptor: su firma ECDSA demuestra que la factura proviene de usted, y el sello propio de ZATCA sobre ella es lo que realmente la hace legalmente válida.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificadores obligatorios', '[["UUID", "Único por factura"], ["IRN", "Número de Referencia de Factura"], ["Hash de la factura", "Encadenado al hash de la factura anterior"], ["Valor de contador de factura", "Numeración secuencial, a prueba de manipulaciones"]]', 'Un rechazo por "Hash Mismatch" significa que el contenido XML se alteró después de calcular el hash — este es uno de los errores más comunes en la integración de la Fase 2.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Format', '[["Syntax", "UBL-2.1-XML, mit ZATCA-spezifischen Erweiterungen"], ["Standard-Rechnungsverpackung", "PDF/A-3 mit eingebettetem XML"], ["Sprache", "Arabisch, maschinenlesbar (zweisprachig in der Praxis üblich)"]]', 'Die PDF/A-3-Verpackung mit eingebettetem XML spiegelt Frankreichs Factur-X-Ansatz wider — eine menschenlesbare Darstellung zusammen mit den maschinenlesbaren Daten in einer einzigen Datei.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Kryptografische Kontrollen', '[["Signaturalgorithmus", "ECDSA (Elliptic Curve Digital Signature Algorithm)"], ["Berechtigungsnachweis", "Cryptographic Stamp Identifier (CSID)"], ["Behördenebene", "ZATCA bringt nach der Freigabe mit ihrem privaten Schlüssel ihren eigenen Stempel an"]]', 'Die Vertrauenskette verläuft Lieferant → ZATCA → Empfänger: Ihre ECDSA-Signatur belegt, dass die Rechnung von Ihnen stammt, und ZATCAs eigener Stempel darauf macht sie tatsächlich rechtsgültig.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Pflichtkennungen', '[["UUID", "Eindeutig pro Rechnung"], ["IRN", "Invoice Reference Number"], ["Rechnungs-Hash", "Verkettet mit dem Hash der vorherigen Rechnung"], ["Rechnungszählerwert", "Fortlaufende, manipulationssichere Nummerierung"]]', 'Eine Ablehnung wegen "Hash Mismatch" bedeutet, dass der XML-Inhalt nach der Hash-Berechnung verändert wurde — dies ist einer der häufigsten Integrationsfehler in Phase 2.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Format', '[["Syntaxe", "XML UBL 2.1, avec extensions spécifiques à ZATCA"], ["Emballage de facture standard", "PDF/A-3 avec XML intégré"], ["Langue", "Arabe, lisible par machine (bilingue courant en pratique)"]]', 'L''emballage PDF/A-3 avec XML intégré reflète l''approche Factur-X de la France — une représentation lisible par l''humain accompagnée des données lisibles par machine dans un seul fichier.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Contrôles cryptographiques', '[["Algorithme de signature", "ECDSA (Elliptic Curve Digital Signature Algorithm)"], ["Justificatif", "Identifiant de cachet cryptographique (CSID)"], ["Couche gouvernementale", "ZATCA appose son propre cachet avec sa clé privée après le contrôle"]]', 'La chaîne de confiance va du fournisseur → ZATCA → destinataire : votre signature ECDSA prouve que la facture provient de vous, et le cachet propre de ZATCA apposé par-dessus est ce qui la rend réellement valide juridiquement.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiants obligatoires', '[["UUID", "Unique par facture"], ["IRN", "Numéro de référence de facture"], ["Hash de la facture", "Chaîné au hash de la facture précédente"], ["Valeur du compteur de factures", "Numérotation séquentielle, inviolable"]]', 'Un rejet « Hash Mismatch » signifie que le contenu XML a été modifié après le calcul du hash — c''est l''une des erreurs d''intégration de phase 2 les plus courantes.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'Código QR (Fase 2)', 'Formato Base64, TLV (Etiqueta-Longitud-Valor), que incluye:', 'Cualquiera puede verificarlos al instante con la app oficial de ZATCA — un escaneo confirma que la factura existe en el sistema central, que sus firmas son válidas y que sus datos impresos coinciden, normalmente en 2–5 segundos.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'Saudi Arabia' AND lc.section = 'file_format' AND lc.sort_order = 3;
