INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Code QR (phase 2)', 'Format Base64, TLV (Tag-Length-Value), incluant :', 'Chacun peut les vérifier instantanément à l''aide de l''application officielle de ZATCA — un scan confirme que la facture existe dans le système central, que ses signatures sont valides et que ses données imprimées correspondent, généralement en 2 à 5 secondes.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'Saudi Arabia' AND lc.section = 'file_format' AND lc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Nom du vendeur' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Numéro de TVA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Horodatage' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Total de la facture' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Total TVA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Hash du cachet cryptographique' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Clé publique' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Signature ECDSA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Saudi Arabia' AND lcc.section = 'file_format' AND lcc.sort_order = 3 AND ls.sort_order = 7;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'B2B — compensación en tiempo real', '[["Umbral", "Facturas superiores a SAR 1.000"], ["Requisito", "Compensada por ZATCA antes de la entrega al comprador"], ["Si no se compensa", "Sin efecto legal ni fiscal"]]', 'Esto es más estricto que el KSeF de Polonia o el SDI de Italia en un sentido concreto — la compensación debe ocurrir antes de la entrega, no solo antes de que la factura se considere "definitiva".', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'B2C — reporte casi en tiempo real', '[["Tipo de documento", "Factura Fiscal Simplificada"], ["Plazo", "Reportada dentro de las 24 horas posteriores a la emisión"]]', 'A diferencia del B2B, las facturas simplificadas pueden emitirse al cliente de inmediato — el plazo de 24 horas cubre el reporte a ZATCA, no la compensación previa.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Códigos de rechazo comunes', '[["401 Unauthorized", "CSID caducado o inválido"], ["BR-KSA-31", "Código de categoría de IVA incorrecto en una línea"], ["Hash Mismatch", "XML alterado tras el cálculo del hash"]]', 'Renovar su CSID antes de que caduque y bloquear la modificación del XML tras calcular el hash son las dos correcciones de mayor impacto para reducir el volumen de rechazos.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Alcance', '[["Se aplica a", "Personas sujetas a impuestos residentes en el Reino"], ["No residente registrado a efectos del IVA", "Actualmente exento de emitir facturas electrónicas"]]', 'Si está registrado a efectos del IVA en Arabia Saudí sin residencia local, actualmente queda fuera del alcance — pero confirme que esto no ha cambiado, ya que el alcance de la facturación electrónica en el CCG se ha modificado antes.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'B2B — Echtzeit-Freigabe', '[["Schwelle", "Rechnungen über SAR 1.000"], ["Anforderung", "Von ZATCA freigegeben vor der Zustellung an den Käufer"], ["Falls nicht freigegeben", "Keine rechtliche oder steuerliche Wirkung"]]', 'Dies ist in einem bestimmten Sinn strenger als Polens KSeF oder Italiens SDI — die Freigabe muss vor der Zustellung erfolgen, nicht nur bevor die Rechnung als "endgültig" gilt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'B2C — Meldung nahezu in Echtzeit', '[["Belegart", "Vereinfachte Steuerrechnung"], ["Frist", "Meldung innerhalb von 24 Stunden nach Ausstellung"]]', 'Anders als bei B2B können vereinfachte Rechnungen dem Kunden sofort ausgestellt werden — die 24-Stunden-Frist betrifft die Meldung an ZATCA, nicht die Vorab-Freigabe.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Häufige Ablehnungscodes', '[["401 Unauthorized", "Abgelaufene oder ungültige CSID"], ["BR-KSA-31", "Falscher Mehrwertsteuer-Kategoriecode für eine Position"], ["Hash Mismatch", "XML nach Hash-Berechnung verändert"]]', 'Die rechtzeitige Erneuerung Ihrer CSID und das Verhindern von XML-Änderungen nach der Hash-Berechnung sind die zwei wirkungsvollsten Maßnahmen zur Reduzierung der Ablehnungsquote.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Anwendungsbereich', '[["Gilt für", "Im Königreich ansässige Steuerpflichtige"], ["Nicht ansässig, umsatzsteuerlich registriert", "Derzeit von der Pflicht zur Ausstellung von E-Rechnungen befreit"]]', 'Wenn Sie in Saudi-Arabien umsatzsteuerlich registriert, aber nicht lokal ansässig sind, fallen Sie derzeit nicht in den Anwendungsbereich — bestätigen Sie jedoch, dass sich dies nicht geändert hat, da sich der Anwendungsbereich für E-Invoicing im GCC bereits verschoben hat.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'B2B — contrôle en temps réel', '[["Seuil", "Factures supérieures à 1 000 SAR"], ["Exigence", "Contrôlée par ZATCA avant livraison à l''acheteur"], ["Si non contrôlée", "Aucun effet juridique ni fiscal"]]', 'Ceci est plus strict que le KSeF polonais ou le SDI italien dans un sens précis — le contrôle doit avoir lieu avant la livraison, pas seulement avant que la facture soit considérée comme « définitive ».', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'B2C — déclaration quasi en temps réel', '[["Type de document", "Facture fiscale simplifiée"], ["Délai", "Déclarée dans les 24 heures suivant l''émission"]]', 'Contrairement au B2B, les factures simplifiées peuvent être émises immédiatement au client — le délai de 24 heures concerne la déclaration à ZATCA, pas le contrôle préalable.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Codes de rejet courants', '[["401 Unauthorized", "CSID expiré ou invalide"], ["BR-KSA-31", "Code de catégorie de TVA incorrect pour une ligne"], ["Hash Mismatch", "XML modifié après le calcul du hash"]]', 'Renouveler votre CSID avant expiration et verrouiller toute modification du XML après le calcul du hash sont les deux correctifs les plus efficaces pour réduire le volume de rejets.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Champ d''application', '[["S''applique à", "Personnes assujetties résidentes du Royaume"], ["Non-résident immatriculé à la TVA", "Actuellement exempté d''émettre des factures électroniques"]]', 'Si vous êtes immatriculé à la TVA en Arabie saoudite sans résidence locale, vous êtes actuellement hors champ — mais vérifiez que cela n''a pas changé, le champ d''application de la facturation électronique dans le CCG ayant déjà évolué.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Registre su organización en el portal Fatoorah', 'Este es el paso previo antes de poder generar cualquier certificado o comenzar el proceso técnico de incorporación.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Genere su Identificador de Sello Criptográfico (CSID)', 'Obténgalo a través de la API de cumplimiento de ZATCA — se requiere antes de poder firmar cualquier factura, así que trátelo como una dependencia bloqueante para todo lo posterior.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure las plantillas de factura', 'Configure todos los campos obligatorios, las traducciones correctas al árabe y la correcta posición del código QR — acierte esto antes de pasar a la firma y las pruebas.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Implemente y pruebe la firma criptográfica', 'Configure la firma ECDSA y genere hashes válidos, luego pruebe explícitamente la verificación de la firma antes de tocar el entorno de pruebas.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Ejecute pruebas exhaustivas en el entorno de pruebas de ZATCA', 'No se salte este paso ni siquiera bajo presión de plazos — está diseñado específicamente para detectar errores de integración antes de que lleguen a producción.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Forme a su equipo de finanzas', 'Asegúrese de que el personal entienda los nuevos procesos, los códigos de rechazo comunes y los procedimientos de resolución de problemas — es un cambio operativo genuino, no solo una actualización de sistema.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pase a producción con las APIs de producción', 'Cambie del entorno de pruebas a producción solo una vez que las pruebas hayan tenido éxito real — y esté atento a la notificación de su ola específica, ya que ZATCA da un aviso de aproximadamente seis meses antes de cada plazo.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie Ihre Organisation auf dem Fatoorah-Portal', 'Dies ist der erforderliche Schritt, bevor Sie Zertifikate erstellen oder mit dem technischen Onboarding beginnen können.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Erstellen Sie Ihren Cryptographic Stamp Identifier (CSID)', 'Beziehen Sie diesen über die Compliance-API von ZATCA — er ist erforderlich, bevor Sie eine Rechnung signieren können, behandeln Sie ihn also als blockierende Abhängigkeit für alles Weitere.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Konfigurieren Sie Rechnungsvorlagen', 'Richten Sie alle Pflichtfelder, korrekte arabische Übersetzungen und die richtige QR-Code-Positionierung ein — bringen Sie dies in Ordnung, bevor Sie zur Signierung und zum Testen übergehen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Implementieren und testen Sie die kryptografische Signierung', 'Konfigurieren Sie die ECDSA-Signierung und erzeugen Sie gültige Hashes, testen Sie dann explizit die Signaturverifizierung, bevor Sie die Sandbox nutzen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Führen Sie umfassende Tests in der ZATCA-Sandbox-Umgebung durch', 'Überspringen Sie diesen Schritt auch unter Zeitdruck nicht — er ist speziell darauf ausgelegt, Integrationsfehler zu erkennen, bevor sie die Produktion erreichen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Schulen Sie Ihr Finanzteam', 'Stellen Sie sicher, dass die Mitarbeiter die neuen Prozesse, häufigen Ablehnungscodes und Fehlerbehebungsverfahren verstehen — dies ist eine echte betriebliche Veränderung, kein reines Systemupdate.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Gehen Sie mit den Produktions-APIs live', 'Wechseln Sie erst dann von der Sandbox zur Produktion, wenn die Tests wirklich erfolgreich waren — und achten Sie auf Ihre spezifische Wellen-Benachrichtigung, da ZATCA vor jeder Frist etwa sechs Monate im Voraus informiert.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Enregistrez votre organisation sur le portail Fatoorah', 'C''est l''étape préalable avant de pouvoir générer des certificats ou commencer l''intégration technique.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Générez votre identifiant de cachet cryptographique (CSID)', 'Obtenez-le via l''API de conformité de ZATCA — il est requis avant de pouvoir signer une facture, traitez-le donc comme une dépendance bloquante pour tout ce qui suit.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Configurez les modèles de facture', 'Configurez tous les champs obligatoires, les traductions correctes en arabe et le bon positionnement du code QR — réglez cela avant de passer à la signature et aux tests.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en œuvre et testez la signature cryptographique', 'Configurez la signature ECDSA et générez des hashs valides, puis testez explicitement la vérification de signature avant de toucher au bac à sable.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Effectuez des tests complets dans l''environnement de bac à sable de ZATCA', 'Ne sautez pas cette étape même sous la pression des délais — elle est spécifiquement conçue pour détecter les erreurs d''intégration avant qu''elles n''atteignent la production.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Formez votre équipe financière', 'Assurez-vous que le personnel comprend les nouveaux processus, les codes de rejet courants et les procédures de dépannage — il s''agit d''un véritable changement opérationnel, pas seulement d''une mise à niveau système.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Passez en production avec les API de production', 'Ne basculez du bac à sable vers la production qu''une fois les tests véritablement réussis — et surveillez votre notification de vague spécifique, ZATCA donnant un préavis d''environ six mois avant chaque échéance.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Saudi Arabia' AND ds.sort_order = 6;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'es', 'Incumplimiento general', 'SAR 5.000 – 50.000 por infracción (~USD 1.333 – 13.333)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Saudi Arabia' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Allgemeine Nichteinhaltung', 'SAR 5.000–50.000 pro Verstoß (~USD 1.333–13.333)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Saudi Arabia' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Non-conformité générale', '5 000 à 50 000 SAR par infraction (~1 333 à 13 333 USD)', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Saudi Arabia' AND pr.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🚫 Funciones de software prohibidas', NULL, NULL, 'Los sistemas conformes con ZATCA no deben permitir la alteración o eliminación de facturas tras su emisión, marcas de tiempo no controladas, ni la desactivación del sello fiscal/criptográfico — los auditores comprueban específicamente estas funciones prohibidas, no solo la ausencia de campos.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📦 Archivado', NULL, NULL, 'La orientación habitual de los proveedores apunta a unos 6 años de datos de facturas electrónicas conservados en almacenamiento accesible — confirme la cifra exacta según la normativa actual de ZATCA para su tipo de negocio.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🌍 Contexto del CCG', NULL, NULL, 'El enfoque de compensación centralizada de Arabia Saudí contrasta claramente con el modelo Peppol descentralizado de 5 esquinas de los EAU, su vecino — algo a tener presente si opera en ambas jurisdicciones, ya que los dos sistemas apenas comparten solapamiento técnico.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🚫 Verbotene Softwarefunktionen', NULL, NULL, 'ZATCA-konforme Systeme dürfen keine Änderung oder Löschung von Rechnungen nach Ausstellung, unkontrollierte Zeitstempel oder das Deaktivieren des Steuer-/Kryptostempels zulassen — Prüfer kontrollieren gezielt auf diese verbotenen Funktionen, nicht nur auf fehlende Felder.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📦 Archivierung', NULL, NULL, 'Gängige Anbieterhinweise gehen von etwa 6 Jahren aufbewahrter E-Rechnungsdaten auf zugänglichem Speicher aus — bestätigen Sie die genaue Zahl anhand der aktuellen ZATCA-Vorschriften für Ihren Unternehmenstyp.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🌍 GCC-Kontext', NULL, NULL, 'Saudi-Arabiens zentralisierter Clearing-Ansatz steht in scharfem Kontrast zum dezentralen Peppol-5-Corner-Modell der benachbarten VAE — wichtig zu bedenken, wenn Sie in beiden Ländern tätig sind, da die beiden Systeme kaum technische Überschneidungen aufweisen.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🚫 Fonctions logicielles interdites', NULL, NULL, 'Les systèmes conformes à ZATCA ne doivent pas permettre la modification ou la suppression de factures après émission, des horodatages non contrôlés, ni la désactivation du cachet fiscal/cryptographique — les auditeurs vérifient spécifiquement ces fonctions interdites, pas seulement les champs manquants.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📦 Archivage', NULL, NULL, 'Les recommandations habituelles des fournisseurs indiquent environ 6 ans de données de factures électroniques conservées sur un stockage accessible — vérifiez le chiffre exact par rapport à la réglementation ZATCA actuelle pour votre type d''entreprise.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🌍 Contexte CCG', NULL, NULL, 'L''approche de contrôle centralisé de l''Arabie saoudite contraste fortement avec le modèle Peppol décentralisé à 5 coins des Émirats arabes unis voisins — à garder à l''esprit si vous opérez dans les deux juridictions, les deux systèmes ne partageant presque aucun recoupement technique.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Saudi Arabia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

